import { useState } from "react";
export default function StudyTracker() {
  const [completed, setCompleted] = useState([]);
  const lessons = ["Structure", "Links", "Forms"];
  return <main><h1>Study tracker</h1>{lessons.map((lesson, i) => <label key={lesson}><input type="checkbox" checked={completed.includes(i)} onChange={e => setCompleted(old => e.target.checked ? [...old, i] : old.filter(x => x !== i))} />{lesson}</label>)}<p>{completed.length} completed</p></main>;
}

import { useState } from "react";
export default function SearchCourses() {
  const [query, setQuery] = useState("");
  const courses = ["HTML", "CSS", "JavaScript", "Python"];
  const shown = courses.filter(name => name.toLowerCase().includes(query.toLowerCase()));
  return <main><label>Search <input value={query} onChange={e => setQuery(e.target.value)} /></label><ul>{shown.map(name => <li key={name}>{name}</li>)}</ul></main>;
}

export default function ErrorState({ error, retry }) {
  if (error) return <section role="alert"><p>Could not load lessons.</p><button onClick={retry}>Try again</button></section>;
  return <p>Lessons loaded.</p>;
}
